#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_autop;
uniform float amzp_aSpeed;
uniform float amzp_progress;
uniform float amzp_scale;
uniform float amzp_angle;
uniform float2 amzp_position;
uniform float2 amzp_stretch;
uniform float amzp_alpha;
uniform float amzp_hardness;
uniform float amzp_blendMode;
uniform float amzp_alphaComp;
uniform float amzp_style;
uniform float amzp_intensity;
uniform float amzp_disp;
uniform float amzp_soft;
uniform float amzp_count;
uniform float amzp_drift;
uniform float amzp_flicker;
uniform float amzp_seed;
uniform float amzp_ringR;
uniform float amzp_ringW;
uniform float amzp_ringArc;
uniform float amzp_striation;
uniform float amzp_sat;
uniform float amzp_core;
uniform float amzp_gradMap;
uniform float amzp_gmTri;
layout(color) uniform half4 amzp_gmFg;
layout(color) uniform half4 amzp_gmMid;
layout(color) uniform half4 amzp_gmBg;
uniform float amzp_samples;
uniform float amzp_overdrawOn;
    float2 advRot(float2 q, float a) { float cs = cos(a), sn = sin(a); return float2(cs * q.x - sn * q.y, sn * q.x + cs * q.y); }
    float4 nmBlend(float4 tex, float4 fx) {
        float4 f = clamp(fx * amzp_hardness, 0.0, 1.0) * clamp(amzp_alpha, 0.0, 1.0);
        float4 b = tex * clamp(amzp_alphaComp, 0.0, 1.0);
        if (int(amzp_blendMode) == 0) return f;
        if (int(amzp_blendMode) == 1) return float4(b.rgb * (f.rgb + (1.0 - f.a)), b.a);
        if (int(amzp_blendMode) == 2) return float4(b.rgb + f.rgb - b.rgb * f.rgb, b.a + f.a - b.a * f.a);
        if (int(amzp_blendMode) == 4) return float4(min(b.rgb + f.rgb, float3(1.0)), max(b.a, f.a));
        return f + b * (1.0 - f.a);
    }
    float4 nmGradMap(float4 fx) {
        if (!(amzp_gradMap>0.5)) return fx;
        float3 un = fx.a > 0.0001 ? fx.rgb / fx.a : float3(0.0);
        float v = clamp(fx.a * (0.25 + 0.75 * dot(un, float3(0.299, 0.587, 0.114))), 0.0, 1.0);
        float4 pB = float4(amzp_gmBg.rgb * amzp_gmBg.a, amzp_gmBg.a), pM = float4(amzp_gmMid.rgb * amzp_gmMid.a, amzp_gmMid.a), pF = float4(amzp_gmFg.rgb * amzp_gmFg.a, amzp_gmFg.a);
        float4 c = (amzp_gmTri>0.5) ? (v < 0.5 ? mix(pB, pM, v * 2.0) : mix(pM, pF, v * 2.0 - 1.0)) : mix(pB, pF, v);
        return c;
    }
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float pxs() { return screen.zw.x / max(screen.zw.x, 1.0); }
    float4 layerAt(float2 uv) { return (uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0) ? amzTexture(0, l2s(uv)) : float4(0.0); }
    float TT() { return (amzp_autop>0.5) ? amzp_progress + time * amzp_aSpeed : amzp_progress; }
    float h1(float n) { return fract(sin(n * 12.9898 + amzp_seed * 78.233) * 43758.5453123); }
    float h21(float2 p) { return fract(sin(dot(p, float2(127.1, 311.7)) + amzp_seed * 17.13) * 43758.5453123); }
    float vn(float2 p) {
        float2 i = floor(p), f = fract(p);
        f = f * f * (3.0 - 2.0 * f);
        return mix(mix(h21(i), h21(i + float2(1.0, 0.0)), f.x), mix(h21(i + float2(0.0, 1.0)), h21(i + float2(1.0, 1.0)), f.x), f.y);
    }
    float sn1(float x) { float i = floor(x), f = fract(x); f = f * f * (3.0 - 2.0 * f); return mix(h1(i), h1(i + 1.0), f); }
    float3 hue(float h) { return clamp(abs(mod(h * 6.0 + float3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0); }
    float3 spec(float l) { return hue(0.78 * (1.0 - l)) * smoothstep(0.0, 0.12, l) * smoothstep(1.0, 0.88, l); }
    float T; float NC; float SF;
    float streaks(float2 q, float k) {
        float s = 0.0;
        for (int i = 0; i < 16; i++) {
            float fi = float(i);
            if (fi >= NC) break;
            float a = (h1(fi * 3.1) - 0.5) * 0.5;
            float2 d = float2(cos(a), sin(a));
            float2 n = float2(-d.y, d.x);
            float off = (h1(fi * 5.7) - 0.5) * 1.6 + sin(T * amzp_drift * (0.5 + h1(fi)) + fi) * 0.15;
            float w = (0.015 + 0.06 * h1(fi * 7.3)) * SF;
            float across = dot(q, n) - off - k * (0.05 + 0.08 * h1(fi * 2.2));
            float c = (h1(fi * 9.1) - 0.5) * 1.6 + sin(T * amzp_drift * 0.7 + fi * 2.0) * 0.4;
            float L = 0.3 + 0.9 * h1(fi * 4.4);
            float al = (dot(q, d) - c) / L;
            float fl = 1.0 - amzp_flicker * sn1(T * 3.0 + fi * 7.0);
            s += exp(-across * across / (w * w)) * exp(-al * al * 2.0) * (0.35 + 0.65 * h1(fi * 6.6)) * fl;
        }
        return s;
    }
    float burst(float2 q, float k) {
        float r = length(q) * (1.0 - k * 0.7);
        float a = atan(q.y, q.x) + k * 0.06;
        float rays = vn(float2(a / 6.28318531 * NC * 2.5 + 10.0, T * amzp_drift * 0.5));
        float rays2 = vn(float2(a / 6.28318531 * NC * 6.0 + 40.0, -T * amzp_drift * 0.3));
        float ray = pow(rays, 3.0) * 1.6 + pow(rays2, 6.0) * 0.8;
        float rad = smoothstep(0.12, 0.45, r) * exp(-r * 1.4 / max(SF, 0.05));
        float fl = 1.0 - amzp_flicker * 0.5 * sn1(T * 2.0);
        return ray * rad * fl * 1.6;
    }
    float ring(float2 q, float k) {
        float rr = length(q) * (1.0 + k * 0.22);
        float a = atan(q.y, q.x);
        float d = (rr - amzp_ringR) / max(amzp_ringW * (0.5 + SF), 1e-4);
        float r = exp(-d * d);
        float ad = abs(atan(sin(a + 3.14159265 * 0.5), cos(a + 3.14159265 * 0.5))) / 3.14159265;
        float arc = 1.0 - smoothstep(amzp_ringArc - 0.12, amzp_ringArc, ad);
        float str = mix(1.0, 0.55 + 0.45 * vn(float2(a * 90.0, 3.0)), amzp_striation);
        return r * arc * str * 1.4;
    }
    float leak(float2 q, float k) {
        float2 qq = q * (1.2 / max(SF + 0.5, 0.1)) + float2(k * 0.35, k * 0.12);
        float s = 0.0;
        for (int i = 0; i < 3; i++) {
            float fi = float(i);
            float2 o = float2(T * amzp_drift * (0.3 + 0.2 * fi), fi * 7.3);
            float v = vn(qq * (1.0 + fi * 0.6) + o);
            s += pow(smoothstep(0.45, 0.95, v), 2.0) * (1.0 - fi * 0.25);
        }
        float fl = 1.0 - amzp_flicker * 0.6 * sn1(T * 1.5 + 3.0);
        return s * fl * (0.4 + 0.6 * clamp(NC / 10.0, 0.0, 1.5));
    }
    float pattern(float2 q, float k) {
        if (int(amzp_style) == 0) return streaks(q, k);
        if (int(amzp_style) == 1) return burst(q, k);
        if (int(amzp_style) == 2) return ring(q, k);
        if (int(amzp_style) == 3) return leak(q, k);
        return streaks(q, k) * 0.5 + burst(q * 1.3, k) * 0.45 + leak(q, k) * 0.45;
    }
    void amzRender() {
        float2 W = layer;
        float2 uv = amzLayerNorm();
        float4 orig = layerAt(uv);
        float ps = pxs();
        T = TT();
        NC = floor(clamp(amzp_count, 1.0, 16.0) + 0.5);
        SF = max(amzp_soft, 0.01);
        float unit = 0.5 * min(W.x, W.y) * max(amzp_scale * 2.0, 0.002);
        float2 ctr = 0.5 * W + float2(amzp_position.x, -amzp_position.y) * ps;
        float2 q = advRot(uv * W - ctr, radians(amzp_angle + 15.0)) / max(amzp_stretch, float2(0.01)) / unit;
        float N = floor(clamp(amzp_samples, 3.0, 32.0) + 0.5);
        float3 acc = float3(0.0), ws = float3(0.0);
        float peak = 0.0;
        for (int j = 0; j < 32; j++) {
            float fj = float(j);
            if (fj >= N) break;
            float l = (fj + 0.5) / N;
            float3 sc = spec(l);
            float I = pattern(q, (l - 0.5) * amzp_disp);
            acc += sc * I;
            ws += sc;
            peak = max(peak, I);
        }
        float3 col = acc / max(ws, float3(1e-4));
        float lum = dot(col, float3(0.2126, 0.7152, 0.0722));
        col = max(mix(float3(lum), col, amzp_sat), 0.0);
        col += float3(amzp_core) * smoothstep(0.5, 1.5, lum) * lum;
        col *= amzp_intensity * 0.9;
        float3 L = 1.0 - exp(-col * 1.3);
        float la = clamp(max(L.r, max(L.g, L.b)), 0.0, 1.0);
        float4 G = float4(L, la);
        amzOutput = nmBlend(orig, nmGradMap(G));
        amzOutput.rgb = min(amzOutput.rgb, float3(amzOutput.a));
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
